    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public payable {
        // Seed the recipient's reward balance through the public entry point.
        // This will transfer 100 wei to recipient (using c's balance).
        bool firstReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint balBefore = address(c).balance;

        // After a successful seeding, rewardsForA[recipient] is 0,
        // so this second withdrawal should transfer 0 wei and not revert.
        bool secondReverted;
        try c.withdrawReward(recipient) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint balAfter = address(c).balance;

        // General rule: if the first bonus withdrawal succeeded, then the reward
        // has already been consumed; a subsequent withdrawReward for the same
        // recipient transfers zero and leaves C's balance unchanged.
        assert(firstReverted || (!secondReverted && balAfter == balBefore));
    }

    receive() external payable {}
}

